using System;
using System.Linq;
using System.Collections;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed class CircuitRaceDirector:MonoBehaviour,IFinchRecoveryHandler {
 public static CircuitRaceDirector Instance;public CircuitSession Session{get;private set;}public RoadPilot[] Opponents{get;private set;}public bool Panel{get;private set;}public bool Results{get;private set;}public bool SavePending{get;private set;}public bool EntryConfirmed;public string Message{get;private set;}public bool Busy=>Panel||Session!=null||SavePending;public bool Ready{get;private set;}
 CircuitEntrant[] previewField;string[] previewSpecs;DocksideTrialDirector trial;RivalRaceDirector duel;FinchVehicle car;TrafficWorld traffic;Vector3 previousPlayer;Vector3[] previousRivals;float[] stall;int[] lastGate;double lastTime;LineRenderer line;Material material;TextMesh marker;bool hudWasEnabled;FinchDrivingHUD hud;
 public static void Hook(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="HarborVale_CityMap")new GameObject("City Stakes | eight real cars and entry fee").AddComponent<CircuitRaceDirector>();}
 IEnumerator Start(){Instance=this;while((duel=RivalRaceDirector.Instance)?.Ready!=true)yield return null;trial=duel.Trial;car=trial.vehicle;traffic=FindAnyObjectByType<TrafficWorld>();hud=car.GetComponent<FinchDrivingHUD>();Ready=true;}
 public bool Open(){if(!Ready||Session!=null||trial.Active||trial.ShowingResult||duel.Race!=null||car.SpeedKph>=5||car.controlsLocked||FindAnyObjectByType<ExpandedWorkshop>()?.IsOpen==true)return false;previewField=CircuitRules.Field("preview");previewSpecs=previewField.Select(e=>{var d=WorkshopCatalog.ForBuild(e.modelId,e.build).Resolve(e.build);return ChassisTuning.CrankHp(d).ToString("F0")+" HP · "+d.massKg.ToString("N0")+" kg\n"+(e.build.induction=="roots"?"SUPERCHARGED V8":e.modelId=="car_tempest"?"TWIN-TURBO EXOTIC":e.build.induction!="none"?"TURBOCHARGED":"NATURALLY ASPIRATED");}).ToArray();Panel=true;EntryConfirmed=false;trial.ExternalModalOpen=true;car.controlsLocked=true;if(hud!=null){hudWasEnabled=hud.enabled;hud.enabled=false;}Message=null;return true;}
 public bool Enter(){if(!Panel||!EntryConfirmed||Session!=null||SavePending)return false;try{var contract=trial.Store.BeginCircuit(Guid.NewGuid().ToString("N"));Session=new CircuitSession(contract,trial.Definition);if(traffic!=null)traffic.ReserveCircuit(trial.Definition.route.Select(p=>p.Position).ToArray());var first=trial.Definition.checkpoints[0];var forward=first.Forward;var right=Vector3.Cross(Vector3.up,forward);Opponents=new RoadPilot[7];previousRivals=new Vector3[7];lastGate=new int[7];stall=new float[7];for(int i=0;i<7;i++){var e=contract.rivals[i];var actor=TrafficWorld.CreateCar(e.name,e.build,e.paint,e.modelId);var p=actor.gameObject.AddComponent<RoadPilot>();p.Car=actor;p.Path=trial.Definition.route.Select(t=>t.Position).ToArray();p.IsRival=true;p.ClosedCourse=true;p.CruiseKph=e.speedKph;p.Lane=1.7f;p.Held=true;p.SeedClosedGrid(i%2==1);actor.ResetAt(first.Position-forward*(12+(i/2)*10)+right*(i%2==0?1.7f:-1.7f)+Vector3.up*.35f,Quaternion.LookRotation(forward));Opponents[i]=p;previousRivals[i]=actor.transform.position;TrafficWorld.Agents.Add(p);}car.ResetAt(first.Position-forward*42-right*1.7f+Vector3.up*.35f,Quaternion.LookRotation(forward));previousPlayer=car.transform.position;car.RecoveryHandler=this;car.controlsLocked=true;Panel=false;Results=false;CreateRoute();lastTime=Time.realtimeSinceStartupAsDouble;Camera.main?.GetComponent<FinchChaseCamera>()?.Snap();return true;}catch(Exception e){Message="Circuit entry/setup: "+e.Message;if(Session!=null)SavePending=true;return false;}}
 void CreateRoute(){material=new Material(Shader.Find("Sprites/Default"));material.color=new Color(.95f,.65f,.2f);var root=new GameObject("Paid circuit route | visual only");root.transform.SetParent(transform,false);line=root.AddComponent<LineRenderer>();line.sharedMaterial=material;line.widthMultiplier=.15f;line.positionCount=trial.Definition.route.Length;line.SetPositions(trial.Definition.route.Select(p=>p.Position+Vector3.up*.16f).ToArray());var label=new GameObject("Circuit checkpoint");label.transform.SetParent(root.transform,false);marker=label.AddComponent<TextMesh>();marker.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");marker.fontSize=48;marker.characterSize=.15f;marker.anchor=TextAnchor.MiddleCenter;marker.alignment=TextAlignment.Center;marker.color=new Color(1,.7f,.2f);label.GetComponent<Renderer>().sharedMaterial=marker.font.material;}
 void Update(){if(!Ready)return;if(Session!=null&&!Results&&!SavePending){float dt=(float)Math.Max(0,Time.realtimeSinceStartupAsDouble-lastTime);lastTime=Time.realtimeSinceStartupAsDouble;var positions=Opponents.Select(p=>p.transform.position).ToArray();Session.Tick(dt,previousPlayer,car.transform.position,previousRivals,positions);previousPlayer=car.transform.position;previousRivals=positions;for(int i=0;i<7;i++){if(lastGate[i]==Session.Rivals[i].NextGate)stall[i]+=dt;else{lastGate[i]=Session.Rivals[i].NextGate;stall[i]=0;}if(Session.Rivals[i].State==TrialState.Running&&(stall[i]>45||Opponents[i].NeedsAssistedReset)){Opponents[i].RecoverAt(Session.Rivals[i].Recover());previousRivals[i]=Opponents[i].transform.position;stall[i]=0;}}if(Session.Resolved)Commit();else{int next=Mathf.Min(Session.Player.NextGate,trial.Definition.checkpoints.Length-1);marker.transform.position=trial.Definition.checkpoints[next].Position+Vector3.up*4;marker.text="CIRCUIT CHECKPOINT "+(next+1)+" / 37";if(Camera.main!=null)marker.transform.rotation=Camera.main.transform.rotation;}}if(FinchInput.Shortcut(KeyCode.Escape)){if(Session!=null&&!Results){Session.Forfeit();Commit();}else if(Panel&&!SavePending)ReturnToRoad();}if(FinchInput.Shortcut(KeyCode.H)&&!Busy&&duel.Race==null&&car.SpeedKph<5){} }
 void LateUpdate(){if(!Ready||!Busy)return;trial.ExternalModalOpen=true;car.controlsLocked=Panel||Results||SavePending||Session?.Player.State==TrialState.Countdown;car.countdownStagingAllowed=Session!=null&&!Results&&Session.Player.State==TrialState.Countdown;if(Session!=null&&Opponents!=null)for(int i=0;i<Opponents.Length;i++){Opponents[i].Held=Results||SavePending||Session.Rivals[i].State!=TrialState.Running;Opponents[i].Car.controlsLocked=Opponents[i].Held;}if(hud!=null&&Session!=null&&!Panel)hud.enabled=!Results;}
 void Commit(){try{trial.Store.SettleCircuit(Session);SavePending=false;Results=Panel=true;int gross=Session.Result.beaten*Session.Contract.perRival;Message=Session.Result.completed?"Finished ahead of "+Session.Result.beaten+" rivals · "+gross.ToString("N0")+" cr paid · net "+(gross-Session.Contract.entryFee).ToString("+#,0;-#,0;0")+" cr.":"Abandoned. The 3,000 cr entry fee is lost; your car remains owned.";if(marker!=null)marker.gameObject.SetActive(false);}catch(Exception e){SavePending=Panel=true;Message="Result not saved: "+e.Message+". Retry before leaving.";}}
 public bool BeforeLeave(){if(SavePending)return false;if(Session!=null&&!Session.Resolved){Session.Forfeit();Commit();}return !SavePending;}
 public void ReturnToRoad(){if(SavePending)return;if(Opponents!=null)foreach(var p in Opponents){TrafficWorld.Agents.Remove(p);if(p!=null)Destroy(p.gameObject);}Opponents=null;Session=null;Panel=Results=false;EntryConfirmed=false;car.controlsLocked=car.countdownStagingAllowed=false;car.RecoveryHandler=duel;trial.ExternalModalOpen=false;if(traffic!=null)traffic.RaceReserved=false;if(line!=null)Destroy(line.gameObject);if(hud!=null)hud.enabled=hudWasEnabled;duel.ApplyVehicle();}
 public bool TryRecover(FinchVehicle vehicle){if(Session==null||Results)return duel.TryRecover(vehicle);if(Session.Player.State!=TrialState.Running)return true;var gate=Session.Player.Recover();vehicle.ResetAt(gate.Position-gate.Forward*5+Vector3.up*.4f,Quaternion.LookRotation(gate.Forward));previousPlayer=vehicle.transform.position;Camera.main?.GetComponent<FinchChaseCamera>()?.Snap();return true;}
 static GUIStyle Style(int size,bool bold=false){var s=new GUIStyle(GUI.skin.label){fontSize=size,wordWrap=true,fontStyle=bold?FontStyle.Bold:FontStyle.Normal};s.normal.textColor=Color.white;return s;}
 void OnGUI(){if(!Ready||!Busy)return;if(!Panel&&Session!=null){GUI.Box(new Rect(16,205,600,65),"CITY STAKES · "+Session.Position+" / 8 · gate "+Session.Player.NextGate+" / 37\n3,000 cr entry paid · 1,000 cr per rival beaten · Esc forfeits entry");return;}var matrix=GUI.matrix;var color=GUI.backgroundColor;GUI.depth=-1400;GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1280f,Screen.height/800f,1));var old=GUI.color;GUI.color=new Color(.035f,.065f,.09f);GUI.DrawTexture(new Rect(0,0,1280,800),Texture2D.whiteTexture);GUI.color=old;GUI.Label(new Rect(36,24,1180,49),"CITY STAKES / EIGHT-CAR CIRCUIT",Style(30,true));GUI.Label(new Rect(38,83,1190,68),"Entry: 3,000 cr · Prize: 1,000 cr per rival you finish ahead of\nBeat 3: break even · Beat all 7: 7,000 gross / +4,000 net · Last or abandon: −3,000",Style(21,true));var button=new GUIStyle(GUI.skin.button){fontSize=19,wordWrap=true};GUI.backgroundColor=new Color(.13f,.28f,.31f);if(Results||SavePending){GUI.Label(new Rect(60,207,1160,140),Message,Style(28,true));if(Session?.Result!=null)GUI.Label(new Rect(60,378,1140,130),"Paid entry: "+Session.Contract.entryFee.ToString("N0")+" cr\nRivals beaten: "+Session.Result.beaten+" / 7\nYour car and fitted engine remain yours in this cash-only event.",Style(24));if(SavePending){if(GUI.Button(new Rect(60,645,1160,60),"Retry saving result",button))Commit();}else if(GUI.Button(new Rect(60,645,1160,60),"Return to driving",button))ReturnToRoad();}
 else{var field=previewField;for(int i=0;i<7;i++){var e=field[i];int col=i%4,row=i/4;var r=new Rect(38+col*306,177+row*174,292,161);GUI.Box(r,"");GUI.Label(new Rect(r.x+12,r.y+12,268,55),e.name,Style(21,true));GUI.Label(new Rect(r.x+12,r.y+73,268,72),previewSpecs[i],Style(18));}GUI.Label(new Rect(962,369,266,126),"YOU\n"+trial.Store.ActiveVehicleName+"\n"+trial.Store.Profile.availableCredits.ToString("N0")+" cr available",Style(20,true));EntryConfirmed=GUI.Toggle(new Rect(43,549,1190,57),EntryConfirmed,"I agree to pay 3,000 credits now. Abandoning or closing this event loses the fee.",new GUIStyle(GUI.skin.toggle){fontSize=21,wordWrap=true});GUI.enabled=EntryConfirmed&&trial.Store.Profile.availableCredits>=3000;if(GUI.Button(new Rect(40,623,1198,59),"Pay 3,000 cr & enter circuit",button))Enter();GUI.enabled=true;GUI.Label(new Rect(43,699,1190,33),Message??"Seven real cars use their own power, tires and physics. The race course is reserved from ambient traffic; car titles are not staked.",Style(17));if(GUI.Button(new Rect(40,746,1198,35),"Back without entering",button))ReturnToRoad();}GUI.backgroundColor=color;GUI.matrix=matrix;}
 void OnDestroy(){if(Instance==this)Instance=null;if(material!=null)Destroy(material);}
}
}
